import path from 'path';
import { defineConfig, loadEnv } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig(({ mode }) => {
    const env = loadEnv(mode, '.', '');
    return {
      server: {
        port: 3000,
        host: '0.0.0.0',
      },
      plugins: [react()],
      define: {
        'process.env.API_KEY': JSON.stringify(env.GEMINI_API_KEY),
        'process.env.GEMINI_API_KEY': JSON.stringify(env.GEMINI_API_KEY)
      },
      resolve: {
        alias: {
          '@': path.resolve(__dirname, '.'),
        }
      }
    };
});

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum JobCategory {
  CONSTRUCTION = 'Construction',
  LOGISTICS = 'Logistics',
  HOSPITALITY = 'Hospitality',
  MANUFACTURING = 'Manufacturing',
  IT_SUPPORT = 'IT Support',
  SECURITY = 'Security'
}

export interface WorkerProfile {
  id: string;
  name: string;
  role: string;
  category: JobCategory;
  skills: string[];
  ratePerHour: number;
  available: boolean;
  rating: number;
  experienceYears: number;
  location: string;
  imageUrl: string;
  verified: boolean;
}

export interface StatItem {
  label: string;
  value: string;
  icon: string;
}

export interface AIAnalysisResult {
  suggestedCategory: JobCategory | null;
  suggestedSkills: string[];
  summary: string;
}

export type PageName = 'home' | 'workers' | 'process' | 'enterprise';

import React, { useState } from 'react';
import { WorkerProfile, JobCategory, PageName } from './types';
import { Modal } from './components/Modal';
import { Navbar } from './components/Navbar';
import { Home } from './pages/Home';
import { FindWorkers } from './pages/FindWorkers';
import { HowItWorks } from './pages/HowItWorks';
import { Enterprise } from './pages/Enterprise';
import { Zap, CheckCircle, Globe, Briefcase, ShieldCheck, Mail, Activity } from 'lucide-react';

const App: React.FC = () => {
  // Navigation State
  const [currentPage, setCurrentPage] = useState<PageName>('home');

  // UI Interaction States
  const [activeModal, setActiveModal] = useState<'login' | 'postJob' | 'global' | null>(null);
  const [selectedWorker, setSelectedWorker] = useState<WorkerProfile | null>(null);
  const [notification, setNotification] = useState<{msg: string, type: 'success' | 'info'} | null>(null);

  // Handlers
  const showNotification = (msg: string, type: 'success' | 'info' = 'success') => {
    setNotification({ msg, type });
    setTimeout(() => setNotification(null), 3000);
  };

  const handleLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setActiveModal(null);
    showNotification("Access Granted. Welcome back, Commander.");
  };

  const handlePostJobSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setActiveModal(null);
    showNotification("Deployment Request Received. Agents are analyzing your needs.");
  };

  const handleHireRequest = () => {
    setSelectedWorker(null);
    showNotification("Contract Initiated. Awaiting worker confirmation.");
  };

  const handleContactSupport = (e?: React.MouseEvent) => {
    if(e) e.preventDefault();
    showNotification("Support ticket created. Priority: High.", 'info');
  };

  const handleContactSales = () => {
    showNotification("Sales team notified. Expect contact within 1 hour.");
  };

  // Page Renderer
  const renderPage = () => {
    switch(currentPage) {
      case 'home':
        return <Home onNavigate={setCurrentPage} onOpenGlobal={() => setActiveModal('global')} />;
      case 'workers':
        return <FindWorkers onViewProfile={setSelectedWorker} />;
      case 'process':
        return <HowItWorks />;
      case 'enterprise':
        return <Enterprise onContact={handleContactSales} />;
      default:
        return <Home onNavigate={setCurrentPage} onOpenGlobal={() => setActiveModal('global')} />;
    }
  };

  return (
    <div className="min-h-screen font-sans text-gray-100 selection:bg-primary selection:text-white bg-bg">
      {/* Notification Toast */}
      {notification && (
        <div className="fixed top-24 right-4 z-[110] animate-fade-in bg-dark border border-primary/50 shadow-neon-blue px-6 py-4 rounded-lg flex items-center gap-3">
          <div className="bg-primary/20 p-2 rounded-full">
            <CheckCircle className="w-5 h-5 text-primary" />
          </div>
          <div>
             <h4 className="font-bold text-white text-sm uppercase tracking-wider">System Notification</h4>
             <p className="text-gray-300 text-sm">{notification.msg}</p>
          </div>
        </div>
      )}

      <Navbar 
        currentPage={currentPage} 
        onNavigate={setCurrentPage} 
        onOpenLogin={() => setActiveModal('login')}
        onOpenPostJob={() => setActiveModal('postJob')}
      />

      <main className="min-h-[calc(100vh-5rem)]">
        {renderPage()}
      </main>

      {/* Footer */}
      <footer className="bg-dark/50 pt-20 pb-10 border-t border-white/10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-12 mb-16">
                <div className="col-span-1 md:col-span-2">
                    <div className="flex items-center gap-2 mb-6">
                         <Activity className="text-primary w-6 h-6" />
                         <span className="font-heading font-bold text-xl">WORKFORCE HUB</span>
                    </div>
                    <p className="text-secondary max-w-md mb-6">
                        The future of industrial staffing. We combine AI-driven matching with rigorous vetting to provide the most reliable workforce on the planet.
                    </p>
                </div>

                <div>
                    <h4 className="font-bold text-white mb-6 uppercase tracking-wider text-sm">Platform</h4>
                    <ul className="space-y-4 text-secondary text-sm">
                        <li><button onClick={() => setCurrentPage('workers')} className="hover:text-primary transition-colors">Find Workers</button></li>
                        <li><button onClick={() => setCurrentPage('enterprise')} className="hover:text-primary transition-colors">Enterprise Solutions</button></li>
                        <li><button onClick={(e) => handleContactSupport(e)} className="hover:text-primary transition-colors">Pricing</button></li>
                        <li><button onClick={(e) => handleContactSupport(e)} className="hover:text-primary transition-colors">API Access</button></li>
                    </ul>
                </div>

                <div>
                    <h4 className="font-bold text-white mb-6 uppercase tracking-wider text-sm">Support</h4>
                    <ul className="space-y-4 text-secondary text-sm">
                        <li><button onClick={(e) => handleContactSupport(e)} className="hover:text-primary transition-colors">Help Center</button></li>
                        <li><button onClick={() => setCurrentPage('process')} className="hover:text-primary transition-colors">Verification Process</button></li>
                        <li><button onClick={(e) => handleContactSupport(e)} className="hover:text-primary transition-colors">Contact Us</button></li>
                        <li><button onClick={(e) => handleContactSupport(e)} className="hover:text-primary transition-colors">Privacy Policy</button></li>
                    </ul>
                </div>
            </div>

            <div className="border-t border-white/10 pt-8 flex flex-col md:flex-row justify-between items-center gap-4">
                <p className="text-secondary text-sm">© 2024 Workforce Hub Inc. All rights reserved.</p>
                <div className="flex items-center gap-2 text-xs text-gray-500 font-mono">
                    <span className="w-2 h-2 bg-green-500 rounded-full"></span>
                    SYSTEM OPTIMAL
                </div>
            </div>
        </div>
      </footer>

      {/* MODALS */}

      {/* 1. Worker Profile Modal */}
      <Modal 
        isOpen={!!selectedWorker} 
        onClose={() => setSelectedWorker(null)} 
        title="Worker Profile"
        size="lg"
      >
        {selectedWorker && (
          <div className="space-y-8">
             <div className="flex flex-col md:flex-row gap-6">
                 <div className="w-full md:w-1/3">
                    <div className="aspect-square rounded-xl overflow-hidden border border-white/10 relative">
                        <img src={selectedWorker.imageUrl} alt={selectedWorker.name} className="w-full h-full object-cover" />
                         {selectedWorker.verified && (
                            <div className="absolute bottom-0 left-0 right-0 bg-green-900/80 backdrop-blur text-white text-xs font-bold py-1 text-center border-t border-green-500/30">
                                VERIFIED PERSONNEL
                            </div>
                         )}
                    </div>
                 </div>
                 <div className="w-full md:w-2/3 space-y-4">
                    <div>
                        <h2 className="text-3xl font-heading font-bold text-white">{selectedWorker.name}</h2>
                        <p className="text-primary font-medium text-lg">{selectedWorker.role}</p>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div className="bg-white/5 p-3 rounded-lg border border-white/10">
                            <span className="text-xs text-secondary block uppercase">Hourly Rate</span>
                            <span className="text-xl font-mono font-bold text-white">${selectedWorker.ratePerHour}/hr</span>
                        </div>
                        <div className="bg-white/5 p-3 rounded-lg border border-white/10">
                            <span className="text-xs text-secondary block uppercase">Experience</span>
                            <span className="text-xl font-mono font-bold text-white">{selectedWorker.experienceYears} Years</span>
                        </div>
                        <div className="bg-white/5 p-3 rounded-lg border border-white/10">
                            <span className="text-xs text-secondary block uppercase">Rating</span>
                            <span className="text-xl font-mono font-bold text-white flex items-center gap-1">
                                {selectedWorker.rating} <span className="text-yellow-400 text-sm">★</span>
                            </span>
                        </div>
                        <div className="bg-white/5 p-3 rounded-lg border border-white/10">
                            <span className="text-xs text-secondary block uppercase">Location</span>
                            <span className="text-lg font-bold text-white truncate">{selectedWorker.location}</span>
                        </div>
                    </div>

                    <div>
                        <h4 className="text-white font-bold mb-2 text-sm uppercase">Verified Skills</h4>
                        <div className="flex flex-wrap gap-2">
                            {selectedWorker.skills.map(skill => (
                                <span key={skill} className="bg-primary/10 text-primary border border-primary/20 px-3 py-1 rounded-full text-xs font-mono">
                                    {skill}
                                </span>
                            ))}
                        </div>
                    </div>
                 </div>
             </div>

             <div className="border-t border-white/10 pt-6">
                 <h4 className="text-white font-bold mb-4">Safety & Credentials</h4>
                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                     {['OSHA Certified', 'Background Check Cleared', 'Identity Verified', 'Previous Employment Verified'].map((item, idx) => (
                         <div key={idx} className="flex items-center gap-2 text-secondary text-sm">
                             <ShieldCheck className="w-4 h-4 text-accent" /> {item}
                         </div>
                     ))}
                 </div>
             </div>

             <div className="flex gap-4 pt-4">
                 <button 
                    onClick={handleHireRequest}
                    className="flex-1 bg-primary hover:bg-blue-600 text-white font-bold py-4 rounded-lg shadow-neon-blue transition-all"
                 >
                    HIRE NOW
                 </button>
                 <button 
                    onClick={(e) => handleContactSupport(e)}
                    className="px-6 border border-white/20 hover:bg-white/5 rounded-lg text-white transition-colors flex items-center justify-center"
                 >
                    <Mail className="w-5 h-5" />
                 </button>
             </div>
          </div>
        )}
      </Modal>

      {/* 2. Login Modal */}
      <Modal isOpen={activeModal === 'login'} onClose={() => setActiveModal(null)} title="System Access" size="sm">
         <form onSubmit={handleLoginSubmit} className="space-y-6">
            <div>
                <label className="block text-sm font-medium text-secondary mb-2">Operation ID (Email)</label>
                <input type="email" required className="w-full bg-bg border border-white/10 rounded-lg p-3 text-white focus:border-primary focus:ring-1 focus:ring-primary outline-none" placeholder="agent@workforce.hub" />
            </div>
            <div>
                <label className="block text-sm font-medium text-secondary mb-2">Access Code</label>
                <input type="password" required className="w-full bg-bg border border-white/10 rounded-lg p-3 text-white focus:border-primary focus:ring-1 focus:ring-primary outline-none" placeholder="••••••••" />
            </div>
            <button type="submit" className="w-full bg-primary hover:bg-blue-600 text-white font-bold py-3 rounded-lg transition-all shadow-neon-blue">
                INITIALIZE SESSION
            </button>
         </form>
      </Modal>

      {/* 3. Post Job Modal */}
      <Modal isOpen={activeModal === 'postJob'} onClose={() => setActiveModal(null)} title="New Deployment Request" size="md">
         <form onSubmit={handlePostJobSubmit} className="space-y-6">
            <div className="grid grid-cols-2 gap-4">
                <div className="col-span-2">
                    <label className="block text-sm font-medium text-secondary mb-2">Mission Title</label>
                    <input type="text" required className="w-full bg-bg border border-white/10 rounded-lg p-3 text-white focus:border-primary focus:ring-1 focus:ring-primary outline-none" placeholder="e.g. Senior Site Foreman" />
                </div>
                <div>
                    <label className="block text-sm font-medium text-secondary mb-2">Category</label>
                    <select className="w-full bg-bg border border-white/10 rounded-lg p-3 text-white focus:border-primary focus:ring-1 focus:ring-primary outline-none appearance-none">
                        {Object.values(JobCategory).map(c => <option key={c}>{c}</option>)}
                    </select>
                </div>
                <div>
                    <label className="block text-sm font-medium text-secondary mb-2">Headcount</label>
                    <input type="number" min="1" className="w-full bg-bg border border-white/10 rounded-lg p-3 text-white focus:border-primary focus:ring-1 focus:ring-primary outline-none" defaultValue="1" />
                </div>
                <div className="col-span-2">
                    <label className="block text-sm font-medium text-secondary mb-2">Mission Parameters (Description)</label>
                    <textarea className="w-full bg-bg border border-white/10 rounded-lg p-3 text-white focus:border-primary focus:ring-1 focus:ring-primary outline-none h-32 resize-none" placeholder="Describe required skills, duration, and site conditions..."></textarea>
                </div>
            </div>
            <button type="submit" className="w-full bg-primary hover:bg-blue-600 text-white font-bold py-3 rounded-lg transition-all shadow-neon-blue flex items-center justify-center gap-2">
                <Zap className="w-4 h-4" /> BROADCAST REQUEST
            </button>
         </form>
      </Modal>

      {/* 4. Global Availability Modal */}
      <Modal isOpen={activeModal === 'global'} onClose={() => setActiveModal(null)} title="Global Coverage" size="lg">
        <div className="space-y-6">
             <div className="aspect-video bg-dark border border-white/10 rounded-xl flex items-center justify-center relative overflow-hidden">
                <div className="absolute inset-0 bg-[url('https://upload.wikimedia.org/wikipedia/commons/e/ec/World_map_blank_without_borders.svg')] bg-no-repeat bg-center bg-contain opacity-20 filter invert"></div>
                <div className="relative z-10 text-center">
                    <Globe className="w-12 h-12 text-primary mx-auto mb-2 animate-pulse" />
                    <h4 className="text-xl font-bold text-white">Live Operations Map</h4>
                    <p className="text-secondary text-sm">Tracking 15,000+ active deployments</p>
                </div>
             </div>
             <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                 {['North America', 'Europe', 'Asia Pacific', 'Middle East'].map(region => (
                     <div key={region} className="p-4 bg-white/5 rounded-lg border border-white/10">
                         <h5 className="font-bold text-white mb-1">{region}</h5>
                         <span className="text-xs text-accent flex items-center gap-1">
                             <span className="w-1.5 h-1.5 bg-accent rounded-full animate-pulse"/> Active
                         </span>
                     </div>
                 ))}
             </div>
        </div>
      </Modal>
    </div>
  );
};

export default App;

