import React from 'react';
import { WorkerProfile } from '../types';
import { MapPin, Star, CheckCircle, Clock } from 'lucide-react';

interface WorkerCardProps {
  worker: WorkerProfile;
  onViewProfile: (worker: WorkerProfile) => void;
}

export const WorkerCard: React.FC<WorkerCardProps> = ({ worker, onViewProfile }) => {
  return (
    <div 
      className="group relative bg-dark border border-white/10 rounded-xl overflow-hidden hover:border-primary/50 transition-all duration-300 hover:shadow-neon-blue cursor-pointer flex flex-col h-full"
      onClick={() => onViewProfile(worker)}
    >
      {/* Image Overlay Gradient */}
      <div className="relative h-64 overflow-hidden shrink-0">
        <img 
          src={worker.imageUrl} 
          alt={worker.name} 
          className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-dark via-dark/20 to-transparent" />

        {/* Availability Badge */}
        <div className={`absolute top-4 right-4 px-3 py-1 rounded-full text-xs font-bold border backdrop-blur-md flex items-center gap-2 ${
          worker.available 
            ? 'bg-accent/10 border-accent/50 text-accent' 
            : 'bg-red-500/10 border-red-500/50 text-red-500'
        }`}>
          <span className={`w-2 h-2 rounded-full ${worker.available ? 'bg-accent animate-pulse' : 'bg-red-500'}`} />
          {worker.available ? 'AVAILABLE NOW' : 'BUSY'}
        </div>
      </div>

      <div className="p-5 relative flex-grow flex flex-col">
        {/* Header */}
        <div className="flex justify-between items-start mb-3">
          <div>
            <h3 className="text-xl font-heading font-bold text-white group-hover:text-primary transition-colors">
              {worker.name}
            </h3>
            <p className="text-secondary text-sm flex items-center gap-1 mt-1">
              <MapPin className="w-3 h-3" /> {worker.location}
            </p>
          </div>
          <div className="flex flex-col items-end">
            <span className="text-2xl font-mono font-bold text-white">${worker.ratePerHour}</span>
            <span className="text-xs text-secondary">/hour</span>
          </div>
        </div>

        {/* Role & verification */}
        <div className="flex items-center gap-2 mb-4">
            <span className="text-primary font-medium text-sm">{worker.role}</span>
            {worker.verified && <CheckCircle className="w-4 h-4 text-accent" />}
        </div>

        {/* Skills */}
        <div className="flex flex-wrap gap-2 mb-6">
          {worker.skills.map((skill) => (
            <span 
              key={skill} 
              className="text-xs font-mono text-secondary border border-white/10 px-2 py-1 rounded group-hover:border-primary/30 transition-colors"
            >
              {skill}
            </span>
          ))}
        </div>

        {/* Spacer to push footer down */}
        <div className="flex-grow" />

        {/* Footer Stats */}
        <div className="flex items-center justify-between border-t border-white/10 pt-4 text-sm mb-4">
            <div className="flex items-center gap-1 text-yellow-400">
                <Star className="w-4 h-4 fill-current" />
                <span className="font-bold text-white">{worker.rating}</span>
            </div>
            <div className="flex items-center gap-1 text-secondary">
                <Clock className="w-4 h-4" />
                <span>{worker.experienceYears}y exp</span>
            </div>
        </div>

        {/* CTA */}
        <button 
          onClick={(e) => {
            e.stopPropagation();
            onViewProfile(worker);
          }}
          className="w-full bg-white/5 hover:bg-primary hover:text-white text-white border border-white/10 hover:border-primary font-semibold py-2 rounded transition-all duration-300 uppercase text-xs tracking-wider"
        >
          View Profile
        </button>
      </div>
    </div>
  );
};

import React, { useEffect } from 'react';
import { X } from 'lucide-react';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
  size?: 'sm' | 'md' | 'lg' | 'xl';
}

export const Modal: React.FC<ModalProps> = ({ isOpen, onClose, title, children, size = 'md' }) => {
  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };

    if (isOpen) {
      window.addEventListener('keydown', handleEsc);
      document.body.style.overflow = 'hidden';
    }

    return () => {
      window.removeEventListener('keydown', handleEsc);
      document.body.style.overflow = 'unset';
    };
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  const sizeClasses = {
    sm: 'max-w-md',
    md: 'max-w-lg',
    lg: 'max-w-2xl',
    xl: 'max-w-4xl'
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/80 backdrop-blur-sm animate-fade-in" 
        onClick={onClose}
      />

      {/* Modal Content */}
      <div 
        className={`relative bg-dark border border-white/10 rounded-2xl shadow-2xl w-full ${sizeClasses[size]} flex flex-col max-h-[90vh] animate-scale-up z-10`}
        role="dialog"
        aria-modal="true"
      >
        {/* Header */}
        <div className="p-6 border-b border-white/10 flex justify-between items-center bg-gradient-to-r from-white/5 to-transparent rounded-t-2xl">
            <h2 className="text-2xl font-heading font-bold text-white tracking-wide">{title}</h2>
            <button 
              onClick={onClose} 
              className="text-secondary hover:text-white hover:bg-white/10 transition-all p-2 rounded-full"
              aria-label="Close modal"
            >
                <X className="w-6 h-6" />
            </button>
        </div>

        {/* Scrollable Body */}
        <div className="p-6 overflow-y-auto custom-scrollbar">
            {children}
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { Zap, CheckCircle, Search, Briefcase, ArrowDown } from 'lucide-react';
import { PROCESS_STEPS } from '../constants';

export const HowItWorks: React.FC = () => {
  return (
    <div className="animate-fade-in min-h-screen">
      {/* Header */}
      <div className="bg-dark py-20 border-b border-white/10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
          <div className="inline-block p-3 bg-primary/10 rounded-2xl mb-6">
            <Zap className="w-8 h-8 text-primary" />
          </div>
          <h1 className="text-4xl md:text-5xl font-heading font-bold text-white mb-6">Deployment Protocol</h1>
          <p className="text-xl text-secondary max-w-2xl mx-auto">
             Our proprietary vetting and matching engine ensures zero friction from request to deployment.
          </p>
        </div>
      </div>

      {/* Steps */}
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-20">
        <div className="relative">
          {/* Vertical Line */}
          <div className="absolute left-8 md:left-1/2 top-0 bottom-0 w-px bg-gradient-to-b from-primary via-primary/50 to-transparent md:-translate-x-1/2" />

          <div className="space-y-24">
            {PROCESS_STEPS.map((step, index) => {
              const isEven = index % 2 === 0;
              return (
