import { GoogleGenAI, Type } from "@google/genai";
import { AIAnalysisResult, JobCategory } from "../types";

const apiKey = process.env.API_KEY || '';

// Initialize only if key exists to prevent immediate crashes in environments without keys set up yet
let ai: GoogleGenAI | null = null;
if (apiKey) {
  ai = new GoogleGenAI({ apiKey });
}

export const analyzeJobRequirements = async (userQuery: string): Promise<AIAnalysisResult> => {
  if (!ai) {
    console.warn("API Key not found. Returning mock analysis.");
    return {
      suggestedCategory: null,
      suggestedSkills: [],
      summary: "AI Service Unavailable: Please configure API_KEY."
    };
  }

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: `Analyze the following job requirement text and extract the most likely job category and a list of key skills required.

      Job Requirement Text: "${userQuery}"

      Available Categories: ${Object.values(JobCategory).join(', ')}.
      `,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            suggestedCategory: {
              type: Type.STRING,
              enum: Object.values(JobCategory),
              description: "The most relevant job category from the provided list.",
            },
            suggestedSkills: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "List of 3-5 key skills extracted or inferred from the text.",
            },
            summary: {
              type: Type.STRING,
              description: "A brief, professional summary of the requirement (max 15 words).",
            },
          },
          required: ["suggestedCategory", "suggestedSkills", "summary"],
        },
      },
    });

    const text = response.text;
    if (!text) {
        throw new Error("No response from AI");
    }

    const data = JSON.parse(text);
    return data as AIAnalysisResult;

  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    // Fallback
    return {
      suggestedCategory: null,
      suggestedSkills: [],
      summary: "Could not analyze requirement. Please try again."
    };
  }
};

