  const [activeSkills, setActiveSkills] = useState<string[]>([]);

  // Filter Logic
  const filteredWorkers = useMemo(() => {
    return WORKERS.filter(worker => {
      const matchesSearch = worker.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            worker.role.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = activeCategory === 'All' || worker.category === activeCategory;
      const matchesSkills = activeSkills.length === 0 || activeSkills.some(s => worker.skills.some(ws => ws.toLowerCase().includes(s.toLowerCase())));

      return matchesSearch && matchesCategory && matchesSkills;
    });
  }, [searchTerm, activeCategory, activeSkills]);

  const handleAIFilters = (category: JobCategory | null, skills: string[]) => {
