                        : 'bg-dark text-secondary hover:text-white border border-white/10 hover:border-primary/50'
                    }`}
                >
                    ALL SECTORS
                </button>
                {Object.values(JobCategory).map((cat) => (
                    <button
                        key={cat}
                        onClick={() => setActiveCategory(cat)}
                        className={`whitespace-nowrap px-6 py-3 rounded-lg text-sm font-bold transition-all ${
                            activeCategory === cat 
