              onClick={() => handleNavClick(link.id)} 
              className={`block w-full text-left py-3 px-4 rounded-lg ${
                currentPage === link.id ? 'bg-primary/10 text-primary' : 'text-white hover:bg-white/5'
              }`}
            >
              {link.label}
            </button>
          ))}
          <div className="border-t border-white/10 my-4 pt-4 space-y-3">
            <button 
              onClick={() => { onOpenLogin(); setIsMenuOpen(false); }} 
              className="block w-full text-center text-white bg-white/5 py-3 rounded-lg font-medium"
            >
              Login
            </button>
            <button 
              onClick={() => { onOpenPostJob(); setIsMenuOpen(false); }} 
              className="block w-full text-center bg-primary text-white py-3 rounded-lg font-bold"
            >
              Post Job
            </button>
          </div>
        </div>
      )}
    </nav>
  );
};
